function vapor(){return `<section class="page demo vapor" aria-label="VOLT"><div class="volt-header"><div class="wrap">${nav('vapor')}</div></div><div class="wrap"><section class="volt-intro"><div class="volt-intro-copy"><p class="store-kicker">VOLT / ${t('vapeStoreLabel')}</p><h1 tabindex="-1">${t('vapeNew')}</h1><p>${t('vapeNewDesc')}</p><button class="btn" data-scroll="vapor-catalog">${t('catalog')} ${arrow}</button></div><div class="volt-display" aria-hidden="true"><span class="volt-display-word">VOLT</span>${img('pod1','','class="volt-hero-pod" fetchpriority="high"')}${img('liquid1','','class="volt-hero-liquid" fetchpriority="high"')}${img('pod3','','class="volt-hero-pod2" fetchpriority="high"')}</div></section>
<section class="volt-catalog" id="vapor-catalog"><div class="shop-section-heading"><h2>${t('catalog')}</h2><span class="count" id="vapor-count" aria-live="polite"></span></div><div class="volt-toolbar"><div class="volt-types" role="group" aria-label="${t('productType')}">${['all','device','liquid'].map(type=>`<button data-vape-type="${type}" aria-pressed="${vapeType===type}">${t('type_'+type)}<span>${type==='all'?concepts.length:concepts.filter(p=>p.type===type).length}</span></button>`).join('')}</div><div class="volt-filters"><label class="filter-field">${t('flavor')}<select id="flavor-filter" ${vapeType==='device'?'disabled':''}>${[['all','allFlavors'],['fruit','fruit'],['ice','ice'],['classic','classic']].map(([v,k])=>`<option value="${v}" ${flavor===v?'selected':''}>${t(k)}</option>`).join('')}</select></label><label class="filter-field">${t('nicotine')}<select id="nicotine-filter" ${vapeType==='device'?'disabled':''}><option value="all">${t('allLabels')}</option>${[...new Set(concepts.filter(p=>p.type==='liquid').map(p=>p.nicotine))].map(n=>`<option value="${n}" ${nicotine===String(n)?'selected':''}>${n} ${t('mg')}</option>`).join('')}</select></label><button class="reset" data-reset aria-label="${t('reset')}">↺</button></div></div><div class="products" id="vapor-products"></div></section>${footer('vapor')}</div></section>`;}

function renderClothes(){
 const list=clothes.filter(p=>category==='all'||p.category===category);
 $('#street-count').textContent=`${t('items')}: ${list.length}`;
 $('#street-products').innerHTML=list.map((p,i)=>`<article class="product"><div class="product-photo"><span class="product-index">0${clothes.indexOf(p)+1}</span>${img(p.image,t(p.id),'loading="lazy"')}</div><div class="offgrid-product-info"><div class="product-name"><h3>${t(p.id)}</h3><span class="price">${money(p.price)}</span></div><p class="product-desc">${t(p.id+'d')}</p><form class="product-controls" data-clothing="${p.id}" novalidate><fieldset class="size-picker"><legend>${t('size')}</legend><div class="size-options">${p.sizes.map(s=>`<button type="button" data-size-option="${p.id}" data-size-value="${s}" aria-pressed="${chosenSizes.get(p.id)===s}" aria-label="${t('size')} ${sizeLabel(s)}: ${t(p.id)}">${s==='OS'?t('oneSize'):s}</button>`).join('')}</div></fieldset><label class="sr-only" for="size-${p.id}">${t('size')}: ${t(p.id)}</label><select class="sr-only" tabindex="-1" aria-hidden="true" id="size-${p.id}" name="size" data-size="${p.id}"><option value=""></option>${p.sizes.map(s=>`<option value="${s}" ${chosenSizes.get(p.id)===s?'selected':''}>${sizeLabel(s)}</option>`).join('')}</select><button class="add-product" aria-label="${t('add')}: ${t(p.id)}">${t('add')} <span aria-hidden="true">+</span></button></form></div></article>`).join('');
}
function renderConcepts(){
 const list=concepts.filter(p=>(vapeType==='all'||p.type===vapeType)&&(flavor==='all'||p.type==='liquid'&&p.family===flavor)&&(nicotine==='all'||p.type==='liquid'&&String(p.nicotine)===nicotine));
 $('#vapor-count').textContent=`${t('items')}: ${list.length}`;
 $('#vapor-products').innerHTML=list.length?list.map(p=>`<article class="product"><div class="product-photo"><span class="volt-product-type">${t('type_'+p.type)}</span>${img(p.image,t(p.id),'loading="lazy"')}</div><div class="volt-product-info"><div class="product-name"><h3>${t(p.id)}</h3><span class="price">${money(p.price)}</span></div><p class="product-desc">${p.type==='liquid'?t(p.id+'d')+'<br>50 '+t('ml')+' · '+p.nicotine+' '+t('mg'):t('deviceOnly')}</p><div class="stock-row"><span class="${p.stock?'stock':'out'}">${p.stock?'●':'○'} ${t(p.stock?(p.stock<5?'lowStock':'stock'):'outStock')}</span><span>${p.stock} ${t('units')}</span></div><div class="product-controls"><button data-add-concept="${p.id}" ${!p.stock?'disabled':''} aria-label="${t('add')}: ${t(p.id)}">${t(p.stock?'add':'unavailable')}<span aria-hidden="true">${p.stock?'+':'—'}</span></button></div></div></article>`).join(''):`<div class="empty"><h3>${t('emptyTitle')}</h3><p>${t('emptyText')}</p></div>`;
}

function projectPreview(type){
 if(type==='street')return `<div class="project-visual preview-fashion"><div class="preview-brand">OFFGRID<sup>®</sup><span>001</span></div><div class="preview-fashion-items">${img('raglan','','loading="lazy"')}${img('jeans','','loading="lazy"')}</div><div class="preview-bottom-line">${t('collection')} <span>↗</span></div></div>`;
 if(type==='vapor')return `<div class="project-visual preview-vapor"><div class="preview-brand">VOLT<span>POD / LIQUID</span></div><div class="preview-vape-items">${img('pod1','','loading="lazy"')}${img('liquid1','','loading="lazy"')}${img('pod3','','loading="lazy"')}</div><div class="preview-bottom-line">${t('type_device')} / ${t('type_liquid')} <span>↗</span></div></div>`;
 return `<div class="project-visual preview-salon"><div class="preview-salon-type"><span>maison<br><i>éclat</i></span><small>${t('beautyTitle')}</small></div>${img('photo-1522337360788-8b13dee7a37e',t('beautyTitle'),'loading="lazy"',800)}<span class="preview-salon-arrow">↗</span></div>`;
}

